char *read_next_line(FILE *VFile, char *ptr) {
    if (fgets(ptr, MAX_LINE_LENGTH, VFile) == NULL) {
        return NULL;
    }

    // Find the newline character and replace it with a null terminator
    char *newline = strchr(ptr, '\n');
    if (newline) {
        *newline = '\0';
    }

    return ptr;
}

